const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const version='v0.3 · Hybrid Futuristic · Build 05';
const THEME_KEY='uromed-ui-theme';
let theme='dark';
try { const saved=localStorage.getItem(THEME_KEY);if(['dark','light','system'].includes(saved))theme=saved; } catch {}
const systemTheme=matchMedia('(prefers-color-scheme: dark)');
function applyTheme(){document.documentElement.dataset.theme=theme==='system'?(systemTheme.matches?'dark':'light'):theme;document.querySelector('meta[name="theme-color"]').content=document.documentElement.dataset.theme==='light'?'#f2f7fb':'#0a1529';}
systemTheme.addEventListener('change',applyTheme);
applyTheme();
const themeControl=()=>`<label class="theme-control">Εμφάνιση<select id="themePicker" aria-label="Εμφάνιση εφαρμογής"><option value="dark" ${theme==='dark'?'selected':''}>Dark</option><option value="light" ${theme==='light'?'selected':''}>Light</option><option value="system" ${theme==='system'?'selected':''}>Συσκευή</option></select></label>`;

let state,loadError='',lastRaw,account=null,page='welcome',method='password',activeClinic='clinic-1',selectedPatient='',editingAppointment='',editingPatient='',editingVisit='',amending='',recordQuery='',statsDay='',programDate='',programClinic='',editingExamination='',examCategory='',autoTimer,lastActivity=Date.now(),busy=false;
try {state=load(localStorage);lastRaw=localStorage.getItem(DATA_KEY);}catch(e){loadError='Δεν ήταν δυνατή η ασφαλής φόρτωση των δεδομένων. Δεν αντικαταστάθηκαν οι υπάρχουσες καταχωρίσεις. '+e.message;}
const RECOVERY_KEY='uromed-demo-form-recovery';
const recoveryFields={clinical:['clinicalSmoking',...Object.keys(CLINICAL_FIELDS).map(k=>'clinical_'+k)],examinations:['examTitle','examDate','examCategory','examResult','examRange','examNotes'],patients:['patientSurname','patientName','patientAge','patientAmka','patientPhone','patientNotes'],calendar:['apptPatient','apptDate','apptTime','apptDuration','apptClinic'],visit:['visitDate','visitClinic','visit_reason','visit_history','visit_exam','visit_assessment','visit_plan','amendReason']};
let interrupted=null;
try { const raw=JSON.parse(sessionStorage.getItem(RECOVERY_KEY)||'null');if(raw&&recoveryFields[raw.page]&&typeof raw.username==='string'&&raw.values&&typeof raw.values==='object')interrupted=raw; } catch {}
function clearRecovery(){interrupted=null;try{sessionStorage.removeItem(RECOVERY_KEY);}catch{}}
function captureRecovery(){if(!account||!recoveryFields[page])return;interrupted={username:account.username,page,editingPatient,editingVisit,editingAppointment,editingExamination,selectedPatient,values:Object.fromEntries(recoveryFields[page].filter(id=>$(id)).map(id=>[id,$(id).value]))};try{sessionStorage.setItem(RECOVERY_KEY,JSON.stringify(interrupted));}catch{}}
function recoveryNotice(){return interrupted?.username===account?.username?`<div class="card recovery"><h2>Συνέχεια εργασίας μετά το κλείδωμα</h2><p>Υπάρχει φόρμα που διακόπηκε. Μπορείτε να επαναφέρετε τα πεδία και να ελέγξετε την αποθήκευσή τους.</p><div class="row">${button('Ανάκτηση φόρμας','recoverForm')}${button('Απόρριψη φόρμας','discardRecovery','','secondary')}</div></div>`:'';}

const clinics=()=>['clinic-1','clinic-2',...(state?.settings.hospital?['hospital']:[])].map(id=>({id,name:state?.settings.clinicNames?.[id]||({'clinic-1':'Ιατρείο 1','clinic-2':'Ιατρείο 2',hospital:'Νοσοκομείο'}[id])}));
const enabled=id=>state?.settings.modules?.[id]!==false;
const clinicName=id=>esc(state?.settings.clinicNames?.[id]||({'clinic-1':'Ιατρείο 1','clinic-2':'Ιατρείο 2',hospital:'Νοσοκομείο'}[id]||'—'));
const patient=id=>state.patients.find(p=>p.id===id);
const doctor=()=>account?.role==='doctor';
const button=(label,action,arg='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" data-id="${esc(arg)}">${label}</button>`;
const field=(label,id,value='',type='text',extra='')=>{const mask=type==='text'?(label.includes('ΗΗ/ΜΜ/ΕΕΕΕ')?'date':id==='apptTime'?'time':''):'';return `<label>${label}<input id="${id}" name="${id}" type="${type}" value="${esc(mask?formatMask(value,mask):value)}" ${mask?`data-mask="${mask}" class="masked-input" autocomplete="off" spellcheck="false"`:''} ${extra}></label>`;};
installMasks(document);
const select=(label,id,values,value)=>`<label>${label}<select id="${id}">${values.map(([key,text])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
const patientSelect=(id,value)=>select('Εικονικός ασθενής',id,state.patients.map(p=>[p.id,p.name+' · '+p.age+' ετών']),value||state.patients[0]?.id);
const clinicSelect=(id,value,all=false)=>select('Ιατρείο',id,[...(all?[['','Όλα τα ιατρεία']]:[]),...clinics().map(c=>[c.id,c.name]),...((value==='hospital'||all)&&!state.settings.hospital?[['hospital','Νοσοκομείο · ανενεργό']]:[])],value);
const brand=()=>'<div class="brand"><span class="mark" aria-hidden="true">U</span>UroMed <span>Nexus Suite</span></div>';
const footer=()=>`<footer>Δημιουργός: ΠΑΠΑΔΟΠΟΥΛΟΣ ΓΕΩΡΓΙΟΣ · ${version}<br>Clinical Testing Edition · Αποκλειστικά φανταστικά δεδομένα</footer>`;
const notice=()=>'<div class="notice"><b>Εκπαιδευτικό demo.</b> Μόνο φανταστικοί ασθενείς. Τοπική αποθήκευση στον browser, χωρίς cloud. Οι ρόλοι και η είσοδος είναι προσομοίωση, όχι προστασία πραγματικών φακέλων.</div>';
function toast(message){$('toast').textContent=message;}
function error(message){toast(message);const e=$('formError');if(e){e.textContent=message;e.className='error';}}
function commit(next) {
 if(localStorage.getItem(DATA_KEY)!==lastRaw)throw Error('Τα δεδομένα άλλαξαν σε άλλο παράθυρο. Κρατήστε το κείμενό σας και ανανεώστε τη σελίδα πριν αποθηκεύσετε.');
 next.updatedAt=new Date().toISOString();save(localStorage,next);state=next;lastRaw=localStorage.getItem(DATA_KEY);
}
function update(fn){const next=JSON.parse(JSON.stringify(state));fn(next);commit(next);}
function optionsActions(){return `<details><summary>Περισσότερες ενέργειες</summary><div class="row">${button('BACKUP · Εξαγωγή','backup')}${button('Επαναφορά αντιγράφου','restore','','secondary')}</div><input type="file" id="backupFile" accept=".json,application/json" class="hidden"></details>`;}
function welcome(){return `<main class="welcome hero" aria-label="Υποδοχή UroMed Nexus Suite"><button type="button" class="welcome-image-button" data-action="login" aria-label="Συνέχεια στην είσοδο του UroMed Nexus Suite"><img src="welcome-bg.png?v=original-20261108" width="1672" height="941" fetchpriority="high" alt="UroMed Nexus Suite · Integrated Urology and Andrology Practice Management · Ολοκληρωμένο Σύστημα Διαχείρισης Ουρολογικού και Ανδρολογικού Ιατρείου. Αρχικό γραφικό υποδοχής με γιατρό, λογότυπο, νεφρούς και πλαϊνά εικονίδια."></button><div class="welcome-navigation">${button('Συνέχεια στην είσοδο →','login','','welcome-enter')}${button('Παρουσίαση','landing','','welcome-more')}</div><p class="welcome-version">${version} · Πατήστε την εικόνα ή το κουμπί για είσοδο.</p></main>`;}
function landing(){return `<header class="row between">${brand()}<div class="row">${themeControl()}<span class="pill">${version}</span></div></header><main class="landing"><div class="hero"><div><div class="eyebrow">Clinical Testing Edition / 2026</div><h1>Το ιατρείο σας.<br>Σε μία <span>ενιαία ροή.</span></h1><p class="lead">Από το πρώτο ραντεβού μέχρι τον επανέλεγχο. Ένα σύγχρονο εκπαιδευτικό περιβάλλον για την οργάνωση ουρολογικού και ανδρολογικού ιατρείου.</p><div class="row">${button('Είσοδος στη δοκιμαστική έκδοση →','login')}${button('Γνωρίστε τη ροή','flow','','secondary')}</div><p class="muted">Χωρίς υποχρεωτική αναμονή. Με φανταστικά δεδομένα και τοπική αποθήκευση.</p></div><div class="hero-visual"><div class="row between"><strong>Η ημέρα σας, οργανωμένη</strong><span class="pill">DEMO</span></div><div class="line"><span class="dot"></span><div><small>01 / ΑΣΘΕΝΗΣ</small><p>Βρείτε την πληροφορία που χρειάζεστε.</p></div></div><div class="line"><span class="dot"></span><div><small>02 / ΕΠΙΣΚΕΨΗ</small><p>Καταγράψτε. Ελέγξτε. Αποθηκεύστε.</p></div></div><div class="line"><span class="dot"></span><div><small>03 / ΣΥΝΕΧΕΙΑ</small><p>Επανέλεγχος και αναφορά, στην ίδια ροή.</p></div></div></div></div><div id="flow" class="grid">${[['01','Ασθενείς & ιστορικό','Φανταστικοί φάκελοι με διακριτές επισκέψεις.'],['02','Δύο χώροι εργασίας','Ραντεβού, διάρκεια και έλεγχος επικαλύψεων.'],['03','SAVE · PRINT · BACKUP','Προσχέδια, προεπισκόπηση και εξαγωγή δεδομένων.']].map(([n,t,d])=>`<article class="card"><div class="step-number">${n}</div><h2>${t}</h2><p class="muted">${d}</p></article>`).join('')}</div>${notice()}<p class="muted">Η AI, η τηλεϊατρική και ο συγχρονισμός αποτελούν μελλοντικές ενότητες. Η έκδοση αυτή δεν προορίζεται για πραγματική ιατρική χρήση.</p></main>${footer()}`;}
let loginName='';try{loginName=localStorage.getItem('uromed-remembered-username')||'';}catch{}
function login(){return `<main class="medical-login"><div class="login-stage"><img class="login-art" src="login-screen.png?v=20261108" width="1672" height="941" alt="" aria-hidden="true"><div class="login-return">${button('← Υποδοχή','welcome','','secondary')}</div><span class="login-language" lang="el">Ελληνικά</span><div class="login-mobile-brand">UroMed <span>Nexus Suite</span></div><section class="medical-auth" aria-labelledby="loginHeading"><h1 id="loginHeading">Σύνδεση χρήστη</h1><p class="login-subtitle">Εισάγετε τα στοιχεία πρόσβασής σας</p><div class="tabs" aria-label="Μέθοδος εισόδου">${[['password','Password'],['pin','PIN'],['biometric','Βιομετρικά']].map(([m,l])=>button(l,'method',m,method===m?'active':'')).join('')}</div><form id="loginForm">${field('Όνομα χρήστη — Username','username',loginName,'text','autocomplete="username" required maxlength="50" placeholder="doctor / reception / ADMIN"')}${method==='password'?`<label>Κωδικός πρόσβασης — Password<div class="password-wrap"><input id="loginSecret" type="password" autocomplete="current-password" required placeholder="Εισάγετε τον κωδικό πρόσβασης">${button('Εμφάνιση','reveal','','secondary')}</div></label>`:method==='pin'?field('Τοπικό PIN · 6 ψηφία','loginSecret','','password','inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="off" required'):'<p class="login-bio-note">Δακτυλικό αποτύπωμα / Face ID / Windows Hello, εφόσον έχει καταχωριστεί από τις Ρυθμίσεις και υποστηρίζεται από τη συσκευή σας.</p>'}<label class="login-remember"><input type="checkbox" id="rememberUsername" ${rememberedUsername()?'checked':''}>Να θυμάται μόνο το όνομα χρήστη</label><div id="formError" role="alert"></div><button type="submit" id="loginSubmit">${method==='biometric'?'Είσοδος με βιομετρικά':'Σύνδεση'} →</button></form><div class="login-support">${button('Δοκιμαστικοί λογαριασμοί / Βοήθεια','loginAccounts','','secondary')}</div><p class="login-demo-note">Μόνο φανταστικά δεδομένα. Τοπικό demo, χωρίς επαγγελματική ταυτοποίηση ή κρυπτογραφημένη βάση φακέλων.</p></section><span class="login-storage-label">Τοπικά δοκιμαστικά δεδομένα</span><span class="login-access-label">Δοκιμαστική<br>πρόσβαση</span><button type="button" class="login-side-biometric" data-action="method" data-id="biometric" aria-label="Επιλογή βιομετρικής εισόδου"></button><p class="login-credit">${version}<br>Created by Georgios Papadopoulos</p></div></main>`;}
function rememberedUsername(){try{return !!localStorage.getItem('uromed-remembered-username');}catch{return false;}}
const titles={clinical:'Ιατρικός φάκελος · Ουρολογία–Ανδρολογία',examinations:'Εξετάσεις & έγγραφα',home:'Ο χώρος εργασίας σας',patients:'Εικονικοί ασθενείς',record:'Ιστορικό ασθενούς',visit:'Ιατρική επίσκεψη',calendar:'Ραντεβού & επανέλεγχοι',report:'Προεπισκόπηση αναφοράς',settings:'Ρυθμίσεις πρόσβασης',admin:'Administration',visitStart:'Επιλογή ασθενή για επίσκεψη',statistics:'Ιστορικό & Στατιστικά',feedback:'Παρατηρήσεις δοκιμής',program:'Εκτύπωση προγράμματος'};
function render(){
 clearTimeout(autoTimer);$('toast').textContent='';
 if(page==='welcome'){$('app').innerHTML=welcome();return;}
 if(page==='landing'){$('app').innerHTML=landing();return;}
 if(page==='login'||!account){page='login';$('app').innerHTML=login();return;}
 const allowed=account.role==='admin'?['home','settings','admin']:account.role==='doctor'?['home','patients','record','visit','visitStart','calendar','report','clinical','examinations','settings']:['home','patients','calendar','settings'];
 if(enabled('feedback'))allowed.push('feedback');if(doctor()&&enabled('statistics'))allowed.push('statistics');if(account.role!=='admin'&&enabled('programPrint'))allowed.push('program');
 if(!allowed.includes(page))page='home';
 const menu=[['home','⌂ Αρχική'],...(account.role!=='admin'?[['patients','Α · Ασθενείς'],['calendar','Α · Ραντεβού']]:[]),...(doctor()?[['record','Β · Ιστορικό επισκέψεων'],['clinical','Β / Γ · Ιατρικός φάκελος'],['examinations','Β · Εξετάσεις & έγγραφα'],['visit','Νέα επίσκεψη']]:[]),...(doctor()&&enabled('statistics')?[['statistics','Ιστορικό & Στατιστικά']]:[]),...(enabled('feedback')?[['feedback','Παρατηρήσεις']]:[]),['settings','Ρυθμίσεις'],...(account.role==='admin'?[['admin','Administration']]:[])];
 $('app').innerHTML=`<header class="row between">${brand()}<div class="row">${themeControl()}<span class="pill">${esc(account.label)} · ${esc(account.username)}</span>${button('Κλείδωμα','lock','','secondary')}${button('Αποσύνδεση','logout','','secondary')}</div></header><div class="shell"><aside class="sidebar"><nav aria-label="Κύρια πλοήγηση">${menu.map(([id,t])=>button(t,id==='visit'?'newVisit':'nav',id==='visit'?'':id,page===id?'active':'')).join('')}${button('? Βοήθεια','help','','help')}</nav></aside><main><div class="workspace-title row between"><div><div class="eyebrow">${version}</div><h1>${titles[page]}</h1></div><span class="pill">${displayDate(today())}</span></div>${notice()}${recoveryNotice()}${loadError?`<div class="error">${esc(loadError)}</div>${button('Εξαγωγή ακατέργαστων δεδομένων','rawBackup')}`:({home,patients:patientsPage,record:recordPage,clinical:clinicalPage,examinations:examinationsPage,visit:visitPage,visitStart:visitStartPage,calendar:calendarPage,report:reportPage,settings:settingsPage,admin:adminPage,statistics:statisticsPage,feedback:feedbackPage,program:programPage}[page])()}</main></div>${footer()}`;
 for(const id of ['clinicalForm','examForm','patientForm']){const form=$(id);if(form)form.dataset.initial=formSnapshot(form);}
 if(page==='visit'&&!loadError&&state.visits.find(v=>v.id===editingVisit)?.status==='draft'){document.querySelectorAll('#visitForm input,#visitForm textarea,#visitForm select').forEach(el=>el.addEventListener('input',()=>{autoTimer=setTimeout(()=>{try{persistVisit(false);$('draftStatus').textContent='Αποθηκεύτηκε τοπικά στις '+new Intl.DateTimeFormat('el-GR',{timeZone:'Europe/Athens',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());}catch(e){$('draftStatus').textContent='Δεν αποθηκεύτηκε: '+e.message;}},700);}));}
}
function home(){if(account.role==='admin')return `<div class="card"><h2>Κέντρο διαχείρισης · εκπαιδευτική έκδοση</h2><p>Ορίστε το PIN/βιομετρικό του ADMIN και δείτε τις διαθέσιμες ενότητες. Για την κλινική ροή χρησιμοποιήστε τον δοκιμαστικό λογαριασμό doctor.</p><div class="row">${button('Διαχείριση λειτουργιών','nav','admin')}${button('Πρόσβαση και PIN','nav','settings','secondary')}</div></div>`;return `<div class="grid">${clinics().map(c=>`<article class="card clinic"><h2>${esc(c.name)}</h2><p class="muted">Σημερινό δοκιμαστικό πρόγραμμα</p>${state.appointments.filter(a=>a.date===today()&&a.clinic===c.id&&a.status==='scheduled').sort((a,b)=>a.time.localeCompare(b.time)).map(a=>`<p class="mono">${a.time} · ${esc(patient(a.patientId)?.name)}</p>`).join('')||'<p class="muted">Δεν υπάρχουν ραντεβού σήμερα.</p>'}${button('Άνοιγμα προγράμματος','clinic',c.id,'secondary')}</article>`).join('')}</div><div class="card"><h2>Σύντομες ενέργειες</h2><div class="row">${button('Νέος ασθενής','newPatient')}${button('Νέο ραντεβού','newAppointment')}${doctor()?button('Νέα επίσκεψη','newVisit'):''}${enabled('programPrint')?button('PRINT · Πρόγραμμα','program','','secondary'):''}</div></div>`;}
function patientsPage(){const p=state.patients.find(p=>p.id===editingPatient);return `<div class="card"><h2>${p?'Επεξεργασία εικονικού ασθενή':'Προσθήκη εικονικού ασθενή'}</h2>${p?'<p class="muted">Οι επισκέψεις και τα ραντεβού παραμένουν συνδεδεμένα με τον ίδιο φάκελο.</p>':''}<form id="patientForm">${p&&!p.lastName?`<p class="notice">Προηγούμενη καταχώριση: ${esc(p.name)}. Επιβεβαιώστε Επίθετο και Όνομα στα χωριστά πεδία. Δεν έγινε αυτόματος διαχωρισμός.</p>`:''}<div class="patient-fields">${field('Επίθετο · φανταστικό','patientSurname',p?.lastName||'','text','required maxlength="70" autocomplete="off"')}${field('Όνομα · φανταστικό','patientName',p?.firstName||'','text','required maxlength="70" autocomplete="off"')}${field('Ηλικία','patientAge',p?.age??'','number','required min="0" max="120" step="1"')}${field('Α.Μ.Κ.Α. · προαιρετικός, μόνο φανταστικός','patientAmka',p?.amka||'','text','inputmode="numeric" maxlength="11" pattern="[0-9]{11}"')}${field('Τηλέφωνο · προαιρετικό φανταστικό','patientPhone',p?.phone||'','tel','maxlength="60"')}</div>${doctor()?`<label>Εκπαιδευτικές σημειώσεις<textarea id="patientNotes" placeholder="Σύντομο πλαίσιο του φανταστικού περιστατικού. Αναλυτικά ευρήματα και πλάνο καταγράφονται στην επίσκεψη.">${esc(p?.notes||'')}</textarea></label>`:''}<div id="formError" role="alert"></div><div class="row"><button type="submit">SAVE · ${p?'Αποθήκευση αλλαγών':'Αποθήκευση ασθενή'}</button>${p?button('Ακύρωση αλλαγών','cancelPatient','','secondary'):''}</div></form></div><div class="card"><h2>Αναζήτηση & επιλογή</h2>${field('Αναζήτηση: ονοματεπώνυμο, ηλικία, Α.Μ.Κ.Α. ή τηλέφωνο','search')}<div id="patientResults">${patientRows('')}</div></div>`;}

function patientRows(q){const list=state.patients.filter(p=>matchesPatient(p,q)).sort((a,b)=>(a.lastName||a.name).localeCompare(b.lastName||b.name,'el')||(a.firstName||'').localeCompare(b.firstName||'','el'));return `<div class="table-wrap"><table><thead><tr><th>Ασθενής</th><th>Ηλικία</th><th>Α.Μ.Κ.Α.</th><th>Ενέργειες</th></tr></thead><tbody>${list.map(p=>`<tr><td>${esc(p.name)}<br><small>${esc(p.phone)||'Χωρίς τηλέφωνο'} · ${esc(p.id.slice(0,8))}</small></td><td>${p.age}</td><td class="mono">${esc(p.amka)||'—'}</td><td><div class="row">${doctor()?button('Φάκελος','record',p.id,'secondary'):''}${button('Ραντεβού','followup',p.id)}${button('Επεξεργασία','editPatient',p.id,'secondary')}</div></td></tr>`).join('')}</tbody></table>${!list.length?'<p class="empty">Δεν βρέθηκαν ασθενείς.</p>':''}</div>`;}
function recordPage(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα εικονικό ασθενή.</p>';const list=state.visits.filter(v=>v.patientId===p.id&&[v.reason,v.history,v.exam,v.assessment,v.plan].join(' ').toLocaleLowerCase('el').includes(recordQuery.toLocaleLowerCase('el'))).sort((a,b)=>(b.date+b.updatedAt).localeCompare(a.date+a.updatedAt));return `<div class="card"><h2>Εύρεση ασθενή στο ιστορικό</h2>${field('Αναζήτηση ασθενή · 2–3 πρώτα γράμματα επιθέτου ή Α.Μ.Κ.Α.','historyPatientSearch','','text','autocomplete="off" aria-controls="historyPatientResults"')}<div id="historyPatientResults" aria-live="polite"></div>${patientSelect('recordPatient',p.id)}<h2>${esc(p.name)}</h2><p>${p.age} ετών · Α.Μ.Κ.Α.: ${esc(p.amka)||'Δεν έχει καταχωριστεί'} · ${esc(p.phone)||'Χωρίς τηλέφωνο'}</p><p>${esc(p.notes)}</p>${clinicalAlert(p)}<div class="row">${button('Ιατρικός φάκελος','openClinical',p.id)}${button('Εξετάσεις & έγγραφα','openExams',p.id,'secondary')}${button('Νέα επίσκεψη','newVisit',p.id)}${button('Στοιχεία ασθενή','editPatient',p.id,'secondary')}${button('Ραντεβού επανελέγχου','followup',p.id,'secondary')}</div></div><div class="card"><form id="recordSearchForm"><div class="row">${field('Αναζήτηση κειμένου στις επισκέψεις','recordSearch',recordQuery)}<button type="submit">Αναζήτηση</button>${button('Όλες οι επισκέψεις','clearRecordSearch','','secondary')}</div></form></div>${list.map(v=>`<article class="card record"><div class="row between"><h2>${displayDate(v.date)} · ${clinicName(v.clinic)}</h2><span class="pill">${v.status==='draft'?'Προσχέδιο':'Οριστικοποιημένη'}</span></div><p>${esc(v.reason)||'Κενό προσχέδιο'}</p><p>${esc(v.plan)}</p><small>Καταχώριση: ${esc(v.author)} · ${v.revisions.length} διορθώσεις</small><div class="row actions">${button(v.status==='draft'?'Συνέχεια προσχεδίου':'Διόρθωση με ιστορικό','editVisit',v.id)}${button('PRINT / E-MAIL · Αναφορά','report',v.id,'secondary')}</div>${v.revisions.length?`<details><summary>Προηγούμενες εκδόσεις</summary>${v.revisions.map(r=>`<div class="card"><strong>${esc(r.reason)}</strong><p>${displayDate(r.snapshot.date||v.date)} · ${clinicName(r.snapshot.clinic||v.clinic)}</p>${[['reason','Λόγος'],['history','Ιστορικό'],['exam','Εξέταση'],['assessment','Γνωμάτευση / παρατηρήσεις'],['plan','Πλάνο']].map(([key,label])=>`<p><strong>${label}:</strong> ${esc(r.snapshot[key])||'—'}</p>`).join('')}<small>${esc(r.author)} · ${esc(r.at)}</small></div>`).join('')}</details>`:''}</article>`).join('')||'<p class="empty">Δεν υπάρχουν ακόμη επισκέψεις αυτού του ασθενούς.</p>'}${optionsActions()}`;}
function visitStartPage(){return `<div class="card"><h2>Σε ποιον εικονικό ασθενή αφορά η επίσκεψη;</h2><form id="startVisitForm">${patientSelect('startPatient',selectedPatient)}<button type="submit">Έναρξη προσχεδίου επίσκεψης</button></form><p class="muted">Ελέγξτε το όνομα και την ηλικία πριν ξεκινήσετε. Δεν δημιουργείται επίσκεψη μέχρι να επιβεβαιώσετε.</p></div>`;}
function visitPage(){const v=state.visits.find(v=>v.id===editingVisit);if(!v)return '<p>Επιλέξτε ασθενή για νέα επίσκεψη.</p>';const p=patient(v.patientId);return `<div class="card"><div class="row between"><h2>${esc(p.name)}</h2><span class="pill">${v.status==='final'?'Διόρθωση οριστικής επίσκεψης':'Προσχέδιο'}</span></div>${clinicalAlert(p)}<div class="row">${button('Ιστορικό / φάρμακα / LUTS','openClinical',p.id,'secondary')}${button('Εξετάσεις','openExams',p.id,'secondary')}</div><p class="muted">Η επίσκεψη συνδέεται με τον συγκεκριμένο ασθενή. Μη συμπληρώνετε πραγματικά δεδομένα.</p><form id="visitForm"><div class="grid">${field('Ημερομηνία · ΗΗ/ΜΜ/ΕΕΕΕ','visitDate',displayDate(v.date),'text','inputmode="numeric" placeholder="ΗΗ/ΜΜ/ΕΕΕΕ" required pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}"')}${clinicSelect('visitClinic',v.clinic)}</div>${[['reason','Λόγος επίσκεψης'],['history','Ιστορικό / συμπτώματα'],['exam','Κλινική εξέταση'],['assessment','Γνωμάτευση / παρατηρήσεις του γιατρού'],['plan','Πλάνο / επανέλεγχος']].map(([k,l])=>`<label>${l}<textarea id="visit_${k}">${esc(v[k])}</textarea></label>`).join('')}${v.status==='final'?field('Αιτία διόρθωσης · υποχρεωτική','amendReason',amending,'text','required maxlength="500"'):''}<p class="field-hint">Δεν υπάρχει προκαθορισμένο όριο χαρακτήρων στα κλινικά πεδία. Η διαθέσιμη χωρητικότητα εξαρτάται από τον browser· ελέγχετε την ένδειξη αποθήκευσης.</p><p id="draftStatus" role="status">${v.status==='final'?'Οι διορθώσεις αποθηκεύονται μόνο με επιβεβαίωση.':'Αυτόματη τοπική αποθήκευση προσχεδίου όσο γράφετε.'}</p><div id="formError" role="alert"></div><div class="row"><button type="submit">SAVE · ${v.status==='final'?'Αποθήκευση διόρθωσης':'Αποθήκευση προσχεδίου'}</button>${v.status==='draft'?button('Οριστικοποίηση επίσκεψης','finalize'):''}${button('Πίσω στο ιστορικό','nav','record','secondary')}</div></form></div>`;}
function visitValues(){const date=isoDate($('visitDate').value);if(!date)throw Error('Συμπληρώστε πραγματική ημερομηνία ως ΗΗ/ΜΜ/ΕΕΕΕ.');return {date,clinic:$('visitClinic').value,...Object.fromEntries(['reason','history','exam','assessment','plan'].map(k=>[k,$('visit_'+k).value.trim()]))};}
function persistVisit(finalize=false,manual=false){const original=state.visits.find(v=>v.id===editingVisit);if(!original||!$('visitForm'))return;
 if(original.status==='final'&&!manual)return;
 const values=visitValues();if(finalize&&!values.reason)throw Error('Συμπληρώστε τον λόγο επίσκεψης πριν οριστικοποιήσετε.');
 if(original.status==='final'&&!$('amendReason').value.trim())throw Error('Συμπληρώστε την αιτία διόρθωσης.');
 const changed=Object.entries(values).some(([k,val])=>original[k]!==val);if(!changed&&!finalize)return;
 update(s=>{const v=s.visits.find(v=>v.id===editingVisit);if(v.status==='final')v.revisions.push({at:new Date().toISOString(),author:account.username,reason:$('amendReason').value.trim(),snapshot:Object.fromEntries(['date','clinic','status','author','updatedAt','reason','history','exam','assessment','plan'].map(k=>[k,v[k]]))});Object.assign(v,values,{updatedAt:new Date().toISOString(),author:account.username});if(finalize)v.status='final';});
}
function formSnapshot(form){return JSON.stringify([...form.querySelectorAll('input:not([type=file]),select,textarea')].map(e=>[e.id,e.type==='checkbox'?e.checked:e.value]));}
function flush(){for(const id of ['patientForm','clinicalForm','examForm']){const form=$(id);if(form&&(formSnapshot(form)!==form.dataset.initial||[...form.querySelectorAll('input[type=file]')].some(e=>e.files.length))&&!confirm('Υπάρχουν μη αποθηκευμένες αλλαγές. Έξοδος χωρίς αποθήκευση;'))return false;}if(page==='visit'&&$('visitForm')){const v=state.visits.find(v=>v.id===editingVisit);if(v?.status==='draft')persistVisit();else if(v&&Object.entries(visitValues()).some(([k,val])=>v[k]!==val)){if(!confirm('Οι μη αποθηκευμένες διορθώσεις θα χαθούν. Έξοδος χωρίς αποθήκευση;'))return false;}}return true;}
function calendarPage(){const a=state.appointments.find(a=>a.id===editingAppointment);return `<div class="card"><h2>${a?'Επεξεργασία':'Νέο'} ραντεβού</h2><form id="appointmentForm"><div class="grid">${patientSelect('apptPatient',a?.patientId||selectedPatient)}${field('Ημερομηνία · ΗΗ/ΜΜ/ΕΕΕΕ','apptDate',a?displayDate(a.date):'','text','required inputmode="numeric" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}"')}${field('Ώρα · ΩΩ:ΛΛ (24ωρη)','apptTime',a?.time||'','text','required inputmode="numeric" maxlength="5" pattern="([01][0-9]|2[0-3]):[0-5][0-9]"')}${select('Διάρκεια','apptDuration',[['15','15 λεπτά'],['30','30 λεπτά'],['45','45 λεπτά'],['60','60 λεπτά'],...(a&&![15,30,45,60].includes(a.duration)?[[String(a.duration),a.duration+' λεπτά']]:[])],String(a?.duration||30))}${clinicSelect('apptClinic',a?.clinic||activeClinic)}</div><div id="formError" role="alert"></div><div class="row"><button type="submit">SAVE · Αποθήκευση ραντεβού</button>${a?button('Ακύρωση αλλαγών','newAppointment','','secondary'):''}</div></form></div><div class="card"><h2>Πρόγραμμα</h2><div class="grid">${field('Φίλτρο ημερομηνίας · ΗΗ/ΜΜ/ΕΕΕΕ','filterDate','','text','placeholder="Όλες οι ημερομηνίες"')}${clinicSelect('filterClinic',activeClinic,true)}${select('Κατάσταση','filterStatus',[['scheduled','Προγραμματισμένα'],['completed','Πραγματοποιημένα'],['no-show','Μη προσέλευση'],['cancelled','Ακυρωμένα'],['','Όλα']],'scheduled')}</div><div class="row">${button('Σήμερα','today')}${button('Καθαρισμός φίλτρων','clearFilters','','secondary')}${enabled('programPrint')?button('PRINT · Πρόγραμμα','program','','secondary'):''}</div><div id="appointmentsList">${appointmentRows('','', 'scheduled')}</div></div>`;}
function appointmentRows(date='',clinic='',status='scheduled'){const list=state.appointments.filter(a=>(!date||a.date===date)&&(!clinic||a.clinic===clinic)&&(!status||a.status===status)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return list.map(a=>`<article class="card record"><div class="row between"><h3>${esc(patient(a.patientId)?.name)}</h3><span class="pill">${({scheduled:'Προγραμματισμένο',completed:'Πραγματοποιημένο','no-show':'Μη προσέλευση',cancelled:'Ακυρωμένο'})[a.status]}</span></div><p class="mono">${displayDate(a.date)} · ${a.time} · ${a.duration} λεπτά · ${clinicName(a.clinic)}</p>${a.status==='scheduled'?`<div class="row">${button('Επεξεργασία','editAppointment',a.id,'secondary')}${button('Ακύρωση ραντεβού','cancelAppointment',a.id,'danger')}${doctor()?button('Ιστορικό','record',a.patientId,'secondary'):''}<details><summary>Κατάσταση ραντεβού</summary><div class="row">${button('Πραγματοποιήθηκε','appointmentDone',a.id,'secondary')}${button('Μη προσέλευση','appointmentAbsent',a.id,'secondary')}</div></details></div>`:''}</article>`).join('')||'<p class="empty">Δεν υπάρχουν ραντεβού με αυτά τα φίλτρα.</p>';}
function filterAppointments(){const text=$('filterDate').value.replace(/[^0-9]/g,'')?$('filterDate').value:'',date=text?isoDate(text):'';if(text&&!date){$('appointmentsList').innerHTML='<p class="error">Χρησιμοποιήστε έγκυρη ημερομηνία ΗΗ/ΜΜ/ΕΕΕΕ.</p>';return;}$('appointmentsList').innerHTML=appointmentRows(date,$('filterClinic').value,$('filterStatus').value);}
function reportPage(){const v=state.visits.find(v=>v.id===editingVisit);if(!v)return '<p>Επιλέξτε μια επίσκεψη από το ιστορικό.</p>';const p=patient(v.patientId);return `<div class="actions row">${button('PRINT · Εκτύπωση / PDF','print')}${enabled('email')?button('E-MAIL · Προσχέδιο μηνύματος','email','','secondary'):''}${button('Ραντεβού επανελέγχου','followup',p.id,'secondary')}${button('Ιστορικό','record',p.id,'secondary')}</div><article class="report" id="reportDocument"><div class="eyebrow">Clinical Testing Edition</div><h2>UroMed Nexus Suite</h2><h3>Δοκιμαστική αναφορά επίσκεψης</h3><div class="notice">ΜΟΝΟ ΕΚΠΑΙΔΕΥΤΙΚΗ ΧΡΗΣΗ · ΦΑΝΤΑΣΤΙΚΑ ΔΕΔΟΜΕΝΑ${v.status==='draft'?' · ΠΡΟΣΧΕΔΙΟ':''}</div><p><b>Εικονικός ασθενής:</b> ${esc(p.name)}<br><b>Ημερομηνία:</b> ${displayDate(v.date)}<br><b>Χώρος:</b> ${clinicName(v.clinic)}<br><b>Κατάσταση:</b> ${v.status==='draft'?'Προσωρινή':'Οριστικοποιημένη'}<br><b>Καταχώριση:</b> ${esc(v.author)}</p><hr>${[['reason','Λόγος επίσκεψης'],['history','Ιστορικό / συμπτώματα'],['exam','Κλινική εξέταση'],['assessment','Γνωμάτευση / παρατηρήσεις'],['plan','Πλάνο']].map(([k,l])=>`<section><h3>${l}</h3><p>${esc(v[k])||'Δεν καταχωρίστηκε.'}</p></section>`).join('')}<footer>Δεν αποτελεί πραγματική ιατρική γνωμάτευση ή συνταγή.<br>Δημιουργός εφαρμογής: ΠΑΠΑΔΟΠΟΥΛΟΣ ΓΕΩΡΓΙΟΣ · ${version}</footer></article><div class="card actions" id="emailPanel" hidden><h2>E-MAIL · Έλεγχος πριν αποστολή</h2><p>Ανοίγει το δικό σας πρόγραμμα αλληλογραφίας. Δεν αποστέλλεται αυτόματα μήνυμα και δεν επισυνάπτεται PDF. Για συνημμένο, αποθηκεύστε πρώτα την αναφορά ως PDF από το PRINT.</p><form id="emailForm">${field('Παραλήπτης · ελέγξτε τη διεύθυνση','emailRecipient','','email','required maxlength="200"')}<label>Περιεχόμενο<textarea id="emailBody"></textarea></label><button type="submit">Άνοιγμα προσχεδίου αλληλογραφίας</button></form></div>`;}
function settingsPage(){return `<div class="card"><h2>PIN του ${esc(account.username)}</h2><p class="muted">Το PIN ισχύει μόνο σε αυτόν τον browser. Προηγείται επιβεβαίωση του δοκιμαστικού Password.</p><form id="pinForm">${field('Τρέχον δοκιμαστικό Password','confirmPassword','','password','required autocomplete="current-password"')}${field('Νέο PIN · 6 ψηφία','newPin','','password','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="new-password"')}${field('Επιβεβαίωση PIN','repeatPin','','password','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="new-password"')}<button type="submit">SAVE · Αποθήκευση PIN</button></form><div id="formError" role="alert"></div></div><div class="card"><h2>Δακτυλικό αποτύπωμα / Face ID / Windows Hello</h2><p>Καταχώριση μέσω του πραγματικού μηχανισμού της συσκευής, όπου υποστηρίζεται. Η συσκευή αποφασίζει ποιον τρόπο επαλήθευσης προσφέρει. Απαιτείται HTTPS ή localhost και επιβεβαίωση Password. Η επαλήθευση του demo είναι μόνο τοπική, χωρίς server.</p><form id="biometricForm">${field('Δοκιμαστικό Password για καταχώριση','bioPassword','','password','required autocomplete="current-password"')}<button type="submit">Καταχώριση βιομετρικής πρόσβασης</button></form><p id="bioStatus" class="muted">Η διαθεσιμότητα θα ελεγχθεί κατά την καταχώριση.</p></div>${account.role!=='reception'?`<div class="card"><h2>BACKUP · Φανταστικά δεδομένα</h2><p>Αντίγραφο JSON με ασθενείς, επισκέψεις και ραντεβού. Περιλαμβάνει και τα αποθηκευμένα αρχεία εξετάσεων από IndexedDB. Δεν περιέχει PIN ή βιομετρικά διαπιστευτήρια. Φυλάξτε το αρχείο· η τοπική αποθήκευση δεν είναι αυτόματο backup.</p>${optionsActions()}</div>`:''}`;}
function adminPage(){return `<div class="card"><h2>Βασικές λειτουργίες</h2><p>Ασθενείς, επισκέψεις, ραντεβού, PRINT και BACKUP παραμένουν ενεργά. Η απενεργοποίηση πρόσθετων ενοτήτων δεν διαγράφει δεδομένα.</p>${Object.entries(MODULES).map(([id,name])=>`<div class="module"><div><strong>${name}</strong><small>Υλοποιημένη ενότητα · ενεργοποίηση από εσάς.</small></div><label><input type="checkbox" data-module="${id}" ${enabled(id)?'checked':''}> Ενεργή</label></div>`).join('')}</div><div class="card"><h2>Χώροι εργασίας</h2><div class="module"><strong>Νοσοκομείο · προαιρετικό</strong><label><input type="checkbox" id="hospitalToggle" ${state.settings.hospital?'checked':''}> Ενεργό</label></div><form id="clinicSettingsForm">${['clinic-1','clinic-2','hospital'].map((id,i)=>field(['Όνομα Ιατρείου 1','Όνομα Ιατρείου 2','Όνομα Νοσοκομείου'][i],'name_'+id,state.settings.clinicNames[id],'text','required maxlength="80"')).join('')}${select('Διάστημα μετακίνησης μεταξύ διαφορετικών χώρων','travelMinutes',[[0,'Χωρίς πρόσθετο διάστημα'],[15,'15 λεπτά'],[30,'30 λεπτά'],[45,'45 λεπτά'],[60,'60 λεπτά'],...(state.settings.travelMinutes&&![15,30,45,60].includes(state.settings.travelMinutes)?[[state.settings.travelMinutes,state.settings.travelMinutes+' λεπτά']]:[])].map(([v,l])=>[String(v),l]),String(state.settings.travelMinutes))}<p class="field-hint">Ο έλεγχος εφαρμόζεται σε νέες κρατήσεις/αλλαγές. Δεν μετακινεί αυτόματα τα παλιά ραντεβού.</p><button type="submit">SAVE · Ρυθμίσεις χώρων</button></form><div id="formError" role="alert"></div></div><div class="card"><h2>Μελλοντικές ενότητες</h2>${['Cloud και κοινά δεδομένα','Τηλεϊατρική / REC','AI / υπαγόρευση / OCR','Κλινικά στατιστικά παθήσεων','Επαγγελματική ταυτοποίηση / συνδρομές'].map(t=>`<div class="module"><strong>${t}</strong><span class="pill">Υπό ανάπτυξη · μη διαθέσιμη</span></div>`).join('')}<p class="muted">Η εμφάνιση ενός διακόπτη δεν θα έκανε έτοιμες αυτές τις λειτουργίες. Θα προστεθούν μετά την υλοποίηση και τον έλεγχό τους.</p></div><div class="card"><h2>Δεδομένα επίδειξης</h2><p>Επαναφορά σε 15 πλήρως φανταστικούς ασθενείς με ενδεικτικές επισκέψεις και ραντεβού. <strong>Αντικαθιστά όλες τις τρέχουσες δοκιμές.</strong> Εξάγετε πρώτα BACKUP.</p>${optionsActions()}<form id="resetDemoForm">${field('Για επιβεβαίωση γράψτε ΕΠΑΝΑΦΟΡΑ','resetConfirm','','text','required autocomplete="off"')}<button type="submit" class="danger">Επαναφορά επίδειξης</button></form></div><div class="card"><h2>Δοκιμαστικοί λογαριασμοί</h2>${ACCOUNTS.map(a=>`<p>${esc(a.username)} · ${esc(a.label)}</p>`).join('')}<p class="muted">Το Administration είναι προσομοίωση ρόλου, όχι επαγγελματικό σύστημα εξουσιοδότησης.</p></div>`;}

async function navigate(target){if(!flush())return;page=target;render();if(page==='calendar'&&!loadError)filterAppointments();window.scrollTo(0,0);}
function newVisit(id){if(!id){if(!flush())return;page='visitStart';render();return;}if(!doctor())throw Error('Η καταχώριση επίσκεψης είναι διαθέσιμη στον δοκιμαστικό ρόλο γιατρού.');if(!flush())return;selectedPatient=id||selectedPatient||state.patients[0]?.id;if(!patient(selectedPatient))throw Error('Προσθέστε πρώτα ασθενή.');const v={id:uid(),patientId:selectedPatient,date:today(),clinic:activeClinic,status:'draft',reason:'',history:'',exam:'',assessment:'',plan:'',author:account.username,updatedAt:new Date().toISOString(),revisions:[]};update(s=>s.visits.push(v));editingVisit=v.id;page='visit';render();}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function backup(){if(account.role==='reception')throw Error('Το backup είναι διαθέσιμο στον γιατρό και τον ADMIN του demo.');download('UroMed-demo-backup-'+today()+'.json',JSON.stringify({...state,attachmentFiles:await exportFiles(state.examinations||[])},null,2));toast('Δημιουργήθηκε αρχείο backup. Ελέγξτε τις λήψεις του browser.');}
function helpContent(context){
 const pages={
 home:'Επιλέξτε χώρο για το σημερινό πρόγραμμα ή ξεκινήστε με νέο εικονικό ασθενή. Τα προγραμματισμένα ραντεβού δεν μετρούν ως ολοκληρωμένες ιατρικές επισκέψεις.',
 patients:'Προσθέστε φανταστικό ονοματεπώνυμο, ηλικία και προαιρετικό τηλέφωνο. Το SAVE αποθηκεύει τοπικά. Η επεξεργασία διατηρεί τον κωδικό και τις συνδέσεις με ιστορικό και ραντεβού. Οι συνωνυμίες επιτρέπονται μετά από επιβεβαίωση.',
 record:'Επιλέξτε ασθενή, αναζητήστε κείμενο σε παλιές επισκέψεις και ανοίξτε προσχέδιο ή αναφορά. Οι διορθώσεις οριστικοποιημένης επίσκεψης χρειάζονται αιτία και διατηρούν την προηγούμενη έκδοση.',
 visit:'Οι αλλαγές προσχεδίου αποθηκεύονται τοπικά μετά από σύντομη παύση. Ελέγξτε την ένδειξη αποθήκευσης. Η οριστικοποίηση απαιτεί λόγο επίσκεψης. Τα πεδία δεν συμπληρώνονται αυτόματα με κλινικά ευρήματα. Για διόρθωση οριστικής επίσκεψης επιλέξτε SAVE με αιτία διόρθωσης.',
 calendar:'Ημερομηνία ΗΗ/ΜΜ/ΕΕΕΕ και ώρα ΩΩ:ΛΛ. Η διάρκεια ελέγχεται σε όλο το πρόγραμμα του γιατρού, ακόμη και σε άλλο ιατρείο. Η ακύρωση και η μη προσέλευση διατηρούν την εγγραφή. Η ένδειξη «Πραγματοποιήθηκε» δεν οριστικοποιεί αυτόματα κλινική επίσκεψη.',
 report:'Το PRINT ανοίγει τον διάλογο του browser, όπου μπορείτε να επιλέξετε εκτύπωση ή αποθήκευση PDF. Το E-MAIL ανοίγει προσχέδιο στο δικό σας πρόγραμμα· ελέγχετε παραλήπτη και περιεχόμενο. Δεν επισυνάπτεται αυτόματα PDF.',
 settings:'Ορίστε PIN για τον δικό σας δοκιμαστικό λογαριασμό ή καταχωρίστε συμβατό βιομετρικό. Το BACKUP εξάγει δεδομένα σε JSON χωρίς PIN/βιομετρικά. Η επαναφορά αντικαθιστά τις τρέχουσες δοκιμές μετά από επιβεβαίωση.',
 admin:'Ενεργοποιήστε έτοιμες πρόσθετες ενότητες, ονομάστε τους χώρους και ορίστε διάστημα μετακίνησης. Οι βασικές λειτουργίες παραμένουν ενεργές. Οι ενότητες υπό ανάπτυξη δεν ενεργοποιούνται ακόμη. Η επαναφορά επίδειξης διαγράφει τις τρέχουσες δοκιμές· εξάγετε πρώτα BACKUP.',
 statistics:'Μετρούνται μόνο οριστικοποιημένες επισκέψεις στο επιλεγμένο διάστημα. Μοναδικοί ασθενείς και επισκέψεις είναι διαφορετικοί αριθμοί. Πατήστε μπάρα για τις αντίστοιχες επισκέψεις. Δεν υπολογίζεται αυτόματα ποιότητα φροντίδας ή διάγνωση.',
 program:'Επιλέξτε ημερομηνία και χώρο. Προεπισκοπήστε το πρόγραμμα και πατήστε PRINT. Οι καταστάσεις εμφανίζονται ξεχωριστά από την κλινική ολοκλήρωση.',
 feedback:'Περιγράψτε βήματα, αναμενόμενο αποτέλεσμα και τι συνέβη. Η παρατήρηση μένει τοπικά, με έκδοση/οθόνη/δοκιμαστικό χρήστη. Εξάγετέ την για να την κοινοποιήσετε εσείς· δεν γίνεται αυτόματη αποστολή.'
 };
 return `<h3>${esc(titles[context]||'Οδηγίες')}</h3><p>${esc(pages[context]||pages.home)}</p><p>Μόνο φανταστικά δεδομένα. Χρησιμοποιήστε τακτικά BACKUP. Η τοπική είσοδος είναι εκπαιδευτική, όχι επαγγελματική προστασία φακέλων.</p>`;
}
function statisticsPage(){const from=today().slice(0,7)+'-01';return `<div class="card"><h2>Επισκέψεις και αναδρομή</h2><p class="muted">Αποκλειστικά οριστικοποιημένες επισκέψεις. Δεν ταυτίζονται με τα προγραμματισμένα ραντεβού.</p><form id="statsForm"><div class="grid">${field('Από · ΗΗ/ΜΜ/ΕΕΕΕ','statsFrom',displayDate(from),'text','required')}${field('Έως · ΗΗ/ΜΜ/ΕΕΕΕ','statsTo',displayDate(today()),'text','required')}${clinicSelect('statsClinic','',true)}</div><button type="submit">Εφαρμογή φίλτρων</button><div id="formError" role="alert"></div></form></div><div id="statsResults">${statsResults(from,today(),'')}</div>`;}
function statsResults(from,to,clinic){const stats=visitStats(state,from,to,clinic),max=Math.max(1,...stats.days.map(([,n])=>n));const visits=state.visits.filter(v=>v.status==='final'&&v.date>=from&&v.date<=to&&(!clinic||v.clinic===clinic)&&(!statsDay||v.date===statsDay)).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="grid"><article class="card"><h2>${stats.visits}</h2><p>Οριστικοποιημένες επισκέψεις</p></article><article class="card"><h2>${stats.patients}</h2><p>Μοναδικοί εικονικοί ασθενείς</p></article></div><div class="card"><h2>Επισκέψεις ανά ημέρα</h2><p class="muted">Πατήστε μια ημερομηνία για αναδρομή. Οι αριθμοί ισχύουν για τα παραπάνω φίλτρα.</p>${stats.days.map(([day,n])=>`<button class="statbar" data-action="statsDay" data-id="${day}" aria-pressed="${statsDay===day}" style="--bar-width:${Math.round(n/max*100)}%"><span>${displayDate(day)}</span><span class="bar-track"><span></span></span><strong>${n}</strong></button>`).join('')||'<p class="empty">Δεν υπάρχουν οριστικοποιημένες επισκέψεις στην περίοδο.</p>'}</div><div class="card"><div class="row between"><h2>${statsDay?displayDate(statsDay):'Σχετικές επισκέψεις'}</h2>${button('Όλες στην περίοδο','statsDay','','secondary')}</div><div class="table-wrap"><table><thead><tr><th>Ημερομηνία</th><th>Ασθενής</th><th>Λόγος</th><th>Ενέργεια</th></tr></thead><tbody>${visits.map(v=>`<tr><td>${displayDate(v.date)}</td><td>${esc(patient(v.patientId)?.name)}</td><td>${esc(v.reason)}</td><td>${button('Αναφορά επίσκεψης','report',v.id,'secondary')}</td></tr>`).join('')}</tbody></table></div></div>`;}
function renderStatsResults(){const from=isoDate($('statsFrom').value),to=isoDate($('statsTo').value);if(!from||!to||from>to)throw Error('Ελέγξτε το χρονικό διάστημα ΗΗ/ΜΜ/ΕΕΕΕ.');$('formError').textContent='';$('formError').className='';$('statsResults').innerHTML=statsResults(from,to,$('statsClinic').value);}
function programPage(){programDate=programDate||today();return `<div class="card actions"><div class="grid">${field('Ημερομηνία προγράμματος','programDate',displayDate(programDate),'text','required')}${clinicSelect('programClinic',programClinic,true)}</div><div class="row">${button('PRINT · Εκτύπωση / PDF','print')}${button('Πίσω στα ραντεβού','nav','calendar','secondary')}</div></div><article class="report" id="programDocument">${programDocument()}</article>`;}
function programDocument(){const list=state.appointments.filter(a=>a.date===programDate&&(!programClinic||a.clinic===programClinic)).sort((a,b)=>a.time.localeCompare(b.time));return `<h2>UroMed Nexus Suite</h2><h3>Ημερήσιο πρόγραμμα · ${displayDate(programDate)}</h3><div class="notice">Εκπαιδευτική εκτύπωση · Μόνο φανταστικά δεδομένα</div><p>${programClinic?clinicName(programClinic):'Όλοι οι χώροι'}</p><table><thead><tr><th>Ώρα</th><th>Ασθενής</th><th>Χώρος</th><th>Κατάσταση</th></tr></thead><tbody>${list.map(a=>`<tr><td>${a.time} · ${a.duration}′</td><td>${esc(patient(a.patientId)?.name)}</td><td>${clinicName(a.clinic)}</td><td>${({scheduled:'Προγραμματισμένο',completed:'Πραγματοποιημένο',cancelled:'Ακυρωμένο','no-show':'Μη προσέλευση'})[a.status]}</td></tr>`).join('')}</tbody></table>${!list.length?'<p>Δεν υπάρχουν ραντεβού.</p>':''}<footer>Δημιουργός: ΠΑΠΑΔΟΠΟΥΛΟΣ ΓΕΩΡΓΙΟΣ · ${version}</footer>`;}
function feedbackPage(){const rows=[...(state.feedback||[])].reverse();return `<div class="card"><h2>Αναφορά προβλήματος / Πρόταση βελτίωσης</h2><p class="muted">Αποθηκεύεται μόνο σε αυτόν τον browser. Δεν γίνεται αυτόματη αποστολή. Μη συμπληρώνετε πραγματικά στοιχεία.</p><form id="feedbackForm">${field('Σύντομος τίτλος','feedbackTitle','','text','required maxlength="150"')}${select('Σχετική οθόνη','feedbackPage',Object.entries(titles).map(([id,name])=>[id,name]),'home')}<label>Βήματα, αναμενόμενο αποτέλεσμα και τι συνέβη<textarea id="feedbackDetails" required maxlength="5000"></textarea></label><button type="submit">SAVE · Παρατήρηση</button><div id="formError" role="alert"></div></form></div><div class="card"><div class="row between"><h2>Καταγεγραμμένες παρατηρήσεις</h2>${button('Εξαγωγή παρατηρήσεων','exportFeedback','','secondary')}</div>${rows.map(f=>`<article class="card"><div class="row between"><h3>${esc(f.title)}</h3><span class="pill">${f.status==='done'?'Ολοκληρώθηκε':'Ανοιχτή'}</span></div><p class="prewrap">${esc(f.details)}</p><small>${esc(titles[f.page]||f.page)} · ${esc(f.author)} · ${esc(f.createdAt)} · ${esc(f.version||version)}</small>${account.role==='admin'?`<div class="actions">${button(f.status==='done'?'Επαναφορά σε ανοιχτή':'Σημείωση ως ολοκληρωμένη','feedbackStatus',f.id,'secondary')}</div>`:''}</article>`).join('')||'<p class="empty">Δεν υπάρχουν παρατηρήσεις.</p>'}</div>`;}
const extraActions={
 loginAccounts:()=>{$('helpText').innerHTML=`<h3>Δοκιμαστικοί λογαριασμοί</h3>${ACCOUNTS.map(a=>`<p><strong>${esc(a.label)}</strong><br>Username: <code>${esc(a.username)}</code><br>Password: <code>${esc(a.demoPassword)}</code></p>`).join('')}<p>Το PIN και η βιομετρική πρόσβαση καταχωρίζονται πρώτα από τις Ρυθμίσεις, μετά από είσοδο με Password. Αν δεν λειτουργούν, χρησιμοποιήστε τα παραπάνω δημόσια στοιχεία demo. Η επιλογή απομνημόνευσης κρατά μόνο το όνομα χρήστη, ποτέ τον κωδικό.</p>`;$('help').showModal();},

 previewExam:async id=>{if(!doctor())throw Error('Απαιτείται γιατρός.');const meta=state.examinations.flatMap(e=>e.files).find(f=>f.id===id);if(!meta||!/^image\/(png|jpeg|webp)$/.test(meta.type))return;const blob=await getFile(id);if(!blob)throw Error('Το αρχείο λείπει.');const url=URL.createObjectURL(blob);$('helpText').innerHTML=`<p>${esc(meta.name)} · Ενδεικτική προβολή αρχείου, όχι διαγνωστική αξιολόγηση.</p><img class="exam-preview" src="${url}" alt="${esc(meta.name)}">`;$('help').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});$('help').showModal();},

 openClinical:async id=>{if(!flush())return;selectedPatient=id;page='clinical';render();},
 openExams:async id=>{if(!flush())return;selectedPatient=id;editingExamination='';page='examinations';render();},
 newExam:()=>{if(!flush())return;editingExamination='';render();},
 editExam:id=>{if(!flush())return;const e=state.examinations.find(x=>x.id===id);selectedPatient=e.patientId;editingExamination=id;render();},
 removeExam:async id=>{if(!doctor()||!flush()||!confirm('Να διαγραφεί η δοκιμαστική εξέταση και τα αρχεία της;'))return;const item=state.examinations.find(e=>e.id===id);update(s=>s.examinations=s.examinations.filter(e=>e.id!==id));for(const f of item.files)await deleteFile(f.id);editingExamination='';render();},
 downloadExam:async id=>{if(!doctor())throw Error('Απαιτείται γιατρός.');const meta=state.examinations.flatMap(e=>e.files).find(f=>f.id===id);if(!meta)throw Error('Δεν υπάρχει αρχείο.');const blob=await getFile(id);if(!blob)throw Error('Το αρχείο λείπει από την τοπική αποθήκη.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=meta.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);},

 recoverForm:()=>{if(!interrupted||interrupted.username!==account.username)return;const data=interrupted;if(data.page==='visit'&&!state.visits.some(v=>v.id===data.editingVisit))throw Error('Η επίσκεψη δεν υπάρχει στην τρέχουσα αποθήκη.');editingPatient=data.editingPatient;editingVisit=data.editingVisit;editingAppointment=data.editingAppointment;editingExamination=data.editingExamination||'';selectedPatient=data.selectedPatient;page=data.page;clearRecovery();render();for(const id of recoveryFields[page])if($(id)&&typeof data.values[id]==='string')$(id).value=data.values[id];toast('Η φόρμα ανακτήθηκε. Ελέγξτε τα στοιχεία και πατήστε SAVE.');},
 discardRecovery:()=>{if(!confirm('Να απορριφθούν τα πεδία της διακοπείσας φόρμας;'))return;clearRecovery();render();},

 clearRecordSearch:()=>{recordQuery='';render();},
 statsDay:day=>{statsDay=day;renderStatsResults();},
 appointmentDone:id=>changeAppointmentStatus(id,'completed'),
 appointmentAbsent:id=>changeAppointmentStatus(id,'no-show'),
 program:async()=>{if(!enabled('programPrint'))throw Error('Η ενότητα είναι ανενεργή.');programDate=page==='calendar'?isoDate($('filterDate').value)||today():today();programClinic=page==='calendar'?$('filterClinic').value:activeClinic;await navigate('program');},
 exportFeedback:()=>{if(!enabled('feedback'))throw Error('Η ενότητα είναι ανενεργή.');download('UroMed-paratiriseis-'+today()+'.json',JSON.stringify({version,exportedAt:new Date().toISOString(),feedback:state.feedback||[]},null,2));toast('Εξήχθησαν οι παρατηρήσεις. Δεν στάλθηκαν σε τρίτους.');},
 feedbackStatus:id=>{if(account.role!=='admin')throw Error('Απαιτείται ADMIN.');update(s=>{const f=s.feedback.find(f=>f.id===id);if(f)f.status=f.status==='open'?'done':'open';});render();}
};
function changeAppointmentStatus(id,status){if(!confirm(status==='completed'?'Να σημειωθεί ότι πραγματοποιήθηκε το ραντεβού; Δεν οριστικοποιείται αυτόματα κλινική επίσκεψη.':'Να σημειωθεί μη προσέλευση;'))return;update(s=>s.appointments.find(a=>a.id===id).status=status);render();filterAppointments();toast('Η κατάσταση ενημερώθηκε, χωρίς διαγραφή της εγγραφής.');}

const actions={...extraActions,welcome:()=>navigate('welcome'),landing:()=>navigate('landing'),login:()=>navigate('login'),flow:()=>$('flow').scrollIntoView({behavior:'smooth'}),method:id=>{loginName=$('username')?.value||loginName;method=id;render();},reveal:()=>{const e=$('loginSecret');e.type=e.type==='password'?'text':'password';},nav:navigate,lock:()=>logout(),logout:()=>logout(),help:()=>{ $('helpText').innerHTML=helpContent(page);$('help').showModal();},newPatient:async()=>{if(!flush())return;editingPatient='';page='patients';render();$('patientName')?.focus();},editPatient:async id=>{if(!flush())return;editingPatient=id;page='patients';render();$('patientName').focus();},cancelPatient:()=>{if(!confirm('Να ακυρωθούν οι μη αποθηκευμένες αλλαγές;'))return;editingPatient='';render();},record:async id=>{recordQuery='';selectedPatient=id;await navigate('record');},newVisit,editVisit:async id=>{if(!flush())return;editingVisit=id;selectedPatient=state.visits.find(v=>v.id===id).patientId;amending='';page='visit';render();},finalize:()=>{if(!confirm('Να οριστικοποιηθεί η δοκιμαστική επίσκεψη; Οι επόμενες αλλαγές θα καταγράφονται ως διορθώσεις.'))return;persistVisit(true,true);page='record';render();toast('Η επίσκεψη οριστικοποιήθηκε.');},report:async id=>{editingVisit=id;await navigate('report');},newAppointment:async()=>{editingAppointment='';await navigate('calendar');},followup:async id=>{selectedPatient=id;editingAppointment='';await navigate('calendar');},clinic:async id=>{activeClinic=id;editingAppointment='';await navigate('calendar');$('filterDate').value=displayDate(today());filterAppointments();},editAppointment:async id=>{editingAppointment=id;await navigate('calendar');},cancelAppointment:id=>{if(!confirm('Να ακυρωθεί το ραντεβού; Θα παραμείνει στο ιστορικό ακυρώσεων.'))return;update(s=>s.appointments.find(a=>a.id===id).status='cancelled');if(editingAppointment===id)editingAppointment='';render();filterAppointments();},today:()=>{$('filterDate').value=displayDate(today());filterAppointments();},clearFilters:()=>{$('filterDate').value='';$('filterClinic').value='';$('filterStatus').value='';filterAppointments();},print:()=>window.print(),email:()=>{$('emailPanel').hidden=false;$('emailBody').value=$('reportDocument').innerText;$('emailPanel').scrollIntoView();},backup,restore:()=>{if(account.role==='reception')throw Error('Δεν επιτρέπεται επαναφορά σε αυτόν τον δοκιμαστικό ρόλο.');$('backupFile').click();},rawBackup:()=>download('UroMed-raw-recovery.json',JSON.stringify(Object.fromEntries([DATA_KEY,'uromed-nexus-demo-v0.3-patients','uromed-nexus-demo-v0.2-appointments'].map(k=>[k,localStorage.getItem(k)])),null,2))};
function logout(){if(!flush())return;loginName=rememberedUsername()?localStorage.getItem('uromed-remembered-username'):'';account=null;editingVisit='';selectedPatient='';editingPatient='';page='login';$('help').close();render();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||busy)return;try{await actions[b.dataset.action]?.(b.dataset.id);}catch(err){error(err.message);}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const submit=e.submitter||e.target.querySelector('button[type=submit]');if(submit)submit.disabled=true;try{
 if(e.target.id==='loginForm'){const a=method==='biometric'?await checkBiometric($('username').value):await check($('username').value,method,$('loginSecret').value);loginName=$('username').value;try{if($('rememberUsername')?.checked)localStorage.setItem('uromed-remembered-username',loginName);else localStorage.removeItem('uromed-remembered-username');}catch{}account=a;lastActivity=Date.now();page='home';render();}
 else if(!account)throw Error('Απαιτείται δοκιμαστική είσοδος.');
 else if(e.target.id==='clinicalForm'){if(!doctor())throw Error('Απαιτείται γιατρός.');const value=clinicalValues();update(s=>s.patients.find(p=>p.id===selectedPatient).clinical=value);render();toast('Το ιατρικό / ουρολογικό ιστορικό αποθηκεύτηκε.');}
 else if(e.target.id==='examForm'){await saveExamination();}
 else if(e.target.id==='startVisitForm'){newVisit($('startPatient').value);}
 else if(e.target.id==='recordSearchForm'){recordQuery=$('recordSearch').value.trim();render();}
 else if(e.target.id==='statsForm'){statsDay='';renderStatsResults();}
 else if(e.target.id==='clinicSettingsForm'){if(account.role!=='admin')throw Error('Απαιτείται ADMIN.');const names=Object.fromEntries(['clinic-1','clinic-2','hospital'].map(id=>[id,$('name_'+id).value.trim()]));if(new Set(Object.values(names)).size!==3)throw Error('Χρησιμοποιήστε διαφορετικά ονόματα για κάθε χώρο.');update(s=>{s.settings.clinicNames=names;s.settings.travelMinutes=Number($('travelMinutes').value);});toast('Οι ονομασίες αποθηκεύτηκαν χωρίς αλλαγή των συνδέσεων.');}
 else if(e.target.id==='feedbackForm'){if(!enabled('feedback'))throw Error('Η ενότητα είναι ανενεργή.');const f={id:uid(),title:$('feedbackTitle').value.trim(),details:$('feedbackDetails').value.trim(),page:$('feedbackPage').value,version,author:account.username,createdAt:new Date().toISOString(),status:'open'};if(!f.title||!f.details)throw Error('Συμπληρώστε τίτλο και περιγραφή.');update(s=>s.feedback.push(f));render();toast('Η παρατήρηση αποθηκεύτηκε τοπικά. Δεν στάλθηκε σε τρίτους.');}
 else if(e.target.id==='resetDemoForm'){if(account.role!=='admin')throw Error('Απαιτείται ADMIN.');if($('resetConfirm').value.trim()!=='ΕΠΑΝΑΦΟΡΑ')throw Error('Γράψτε ΕΠΑΝΑΦΟΡΑ για να συνεχίσετε.');if(!confirm('Τελική επιβεβαίωση: αντικατάσταση των τωρινών δοκιμαστικών δεδομένων με τα αρχικά 15 συνθετικά περιστατικά;'))return;commit(demoState());clearRecovery();selectedPatient='';editingPatient='';editingVisit='';editingAppointment='';activeClinic='clinic-1';render();toast('Επαναφέρθηκαν τα συνθετικά δεδομένα επίδειξης.');}
 else if(e.target.id==='patientForm'){const old=state.patients.find(p=>p.id===editingPatient);const firstName=$('patientName').value.trim(),lastName=$('patientSurname').value.trim();if(!firstName||!lastName)throw Error('Συμπληρώστε Επίθετο και Όνομα.');const p={...old,id:old?.id||uid(),firstName,lastName,name:lastName+' '+firstName,age:Number($('patientAge').value),amka:$('patientAmka').value.trim(),phone:$('patientPhone').value.trim(),notes:$('patientNotes')?.value.trim()??old?.notes??''};if(!p.name)throw Error('Συμπληρώστε φανταστικό όνομα.');if(state.patients.some(x=>x.id!==p.id&&x.name.toLocaleLowerCase('el')===p.name.toLocaleLowerCase('el'))&&!confirm('Υπάρχει ίδιο όνομα. Είναι διαφορετικός φανταστικός ασθενής;'))return;update(s=>{const i=s.patients.findIndex(x=>x.id===p.id);if(i<0)s.patients.push(p);else s.patients[i]=p;});selectedPatient=p.id;editingPatient='';render();toast(old?'Τα στοιχεία ενημερώθηκαν. Οι συνδέσεις με επισκέψεις και ραντεβού διατηρήθηκαν.':'Ο εικονικός ασθενής αποθηκεύτηκε.');}
 else if(e.target.id==='appointmentForm'){const date=isoDate($('apptDate').value),time=$('apptTime').value;if(!date||!validTime(time))throw Error('Ελέγξτε ημερομηνία ΗΗ/ΜΜ/ΕΕΕΕ και ώρα ΩΩ:ΛΛ.');const a={id:editingAppointment||uid(),patientId:$('apptPatient').value,date,time,duration:Number($('apptDuration').value),clinic:$('apptClinic').value,status:'scheduled'};if(a.clinic==='hospital'&&!state.settings.hospital)throw Error('Το Νοσοκομείο είναι ανενεργό. Επιλέξτε ενεργό ιατρείο.');if(conflicts(state,a))throw Error('Υπάρχει χρονική επικάλυψη στο πρόγραμμα του γιατρού, ακόμη και σε άλλο ιατρείο. Επιλέξτε άλλη ώρα.');update(s=>{const i=s.appointments.findIndex(x=>x.id===a.id);if(i<0)s.appointments.push(a);else s.appointments[i]=a;});editingAppointment='';render();filterAppointments();toast('Το ραντεβού αποθηκεύτηκε.');}
 else if(e.target.id==='visitForm'){persistVisit(false,true);toast('Η επίσκεψη αποθηκεύτηκε τοπικά.');if(state.visits.find(v=>v.id===editingVisit).status==='final'){page='record';render();}}
 else if(e.target.id==='pinForm'){await check(account.username,'password',$('confirmPassword').value);if($('newPin').value!==$('repeatPin').value)throw Error('Τα PIN δεν συμφωνούν.');await setPin(account,$('newPin').value);e.target.reset();toast('Το τοπικό δοκιμαστικό PIN αποθηκεύτηκε.');}
 else if(e.target.id==='biometricForm'){await check(account.username,'password',$('bioPassword').value);await registerBiometric(account);e.target.reset();$('bioStatus').textContent='Καταχωρίστηκε για αυτόν τον λογαριασμό, browser και προέλευση.';}
 else if(e.target.id==='emailForm'){const to=$('emailRecipient').value.trim();if(/[\r\n]/.test(to))throw Error('Μη έγκυρος παραλήπτης.');location.href='mailto:'+encodeURIComponent(to)+'?subject='+encodeURIComponent('UroMed · Δοκιμαστική αναφορά, μόνο φανταστικά δεδομένα')+'&body='+encodeURIComponent($('emailBody').value);toast('Ζητήθηκε άνοιγμα προγράμματος email. Δεν έγινε αποστολή από την εφαρμογή.');}
 }catch(err){error(err.name==='NotAllowedError'?'Η βιομετρική διαδικασία ακυρώθηκε ή δεν επιτράπηκε. Δοκιμάστε Password ή PIN.':err.message);}finally{busy=false;if(submit)submit.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='search')$('patientResults').innerHTML=patientRows(e.target.value);if(e.target.id==='historyPatientSearch'){$('historyPatientResults').innerHTML=historyPatientResults(e.target.value);}});
function historyPatientResults(query){const q=query.trim();if(!q)return '';if(!/^[0-9]+$/.test(q)&&q.length<2)return '<p class="muted">Γράψτε τουλάχιστον 2 γράμματα επιθέτου.</p>';const list=state.patients.filter(p=>matchesPatient(p,q,{history:true}));return list.length?`<p>${list.length} αποτελέσματα · επιλέξτε τον σωστό φάκελο:</p><div class="patient-matches">${list.map(p=>button(`${esc(p.name)} · ${p.age} ετών · Α.Μ.Κ.Α.: ${esc(p.amka)||'—'}`,'record',p.id,'secondary')).join('')}</div>`:'<p>Δεν βρέθηκαν ασθενείς.</p>';}

document.addEventListener('change',async e=>{try{
 if(['clinicalPatient','examPatient'].includes(e.target.id)){const id=e.target.value;if(!flush()){e.target.value=selectedPatient;return;}selectedPatient=id;editingExamination='';render();}
 if(e.target.id==='examTypeFilter'){if(!flush())return;examCategory=e.target.value;editingExamination='';render();}
 if(e.target.dataset.module){if(account?.role!=='admin')throw Error('Απαιτείται ADMIN.');const id=e.target.dataset.module;if(!Object.hasOwn(MODULES,id))return;const desired=e.target.checked;update(s=>s.settings.modules[id]=desired);toast('Η διαθεσιμότητα της ενότητας ενημερώθηκε. Τα δεδομένα διατηρήθηκαν.');}
 if(['programDate','programClinic'].includes(e.target.id)){programDate=isoDate($('programDate').value);programClinic=$('programClinic').value;if(!programDate)throw Error('Ελέγξτε την ημερομηνία.');$('programDocument').innerHTML=programDocument();}
 if(e.target.id==='themePicker'){const value=e.target.value;if(!['dark','light','system'].includes(value))return;localStorage.setItem(THEME_KEY,value);theme=value;applyTheme();}
 if(e.target.id==='recordPatient'){selectedPatient=e.target.value;recordQuery='';render();}
 if(['filterDate','filterClinic','filterStatus'].includes(e.target.id))filterAppointments();
 if(e.target.id==='hospitalToggle'){if(account?.role!=='admin')throw Error('Απαιτείται δοκιμαστικός ADMIN.');const enabled=e.target.checked;if(!enabled&&state.appointments.some(a=>a.clinic==='hospital'&&a.status==='scheduled'&&a.date>=today()))throw Error('Υπάρχουν μελλοντικά ραντεβού Νοσοκομείου. Μεταφέρετε ή ακυρώστε τα πριν την απενεργοποίηση.');update(s=>s.settings.hospital=enabled);if(!enabled&&activeClinic==='hospital')activeClinic='clinic-1';toast('Η ρύθμιση αποθηκεύτηκε. Το ιστορικό διατηρήθηκε.');}
 if(e.target.id==='backupFile'&&e.target.files[0]){if(account.role==='reception')throw Error('Δεν επιτρέπεται επαναφορά.');const file=e.target.files[0];if(file.size>150*1024*1024)throw Error('Το αντίγραφο υπερβαίνει τα 150 MB.');const parsed=JSON.parse(await file.text());const encoded=parsed.attachmentFiles||[];delete parsed.attachmentFiles;const candidate=normalize(parsed);const restoredFiles=decodeFiles(candidate.examinations,encoded);if(!confirm(`Επαναφορά ${candidate.patients.length} ασθενών, ${candidate.visits.length} επισκέψεων και ${candidate.appointments.length} ραντεβού; Αντικαθιστά τις τωρινές δοκιμές. Εξάγετε πρώτα BACKUP αν θέλετε να τις κρατήσετε.`))return;const added=[];try{for(const f of restoredFiles){const existing=await getFile(f.id);if(existing){if(existing.size!==f.blob.size||await blobFingerprint(existing)!==await blobFingerprint(f.blob))throw Error('Υπάρχει διαφορετικό τοπικό αρχείο με τον ίδιο κωδικό.');}else{await putFile(f.id,f.blob);added.push(f.id);}}commit(candidate);}catch(err){for(const id of added)await deleteFile(id);throw err;}clearRecovery();selectedPatient='';editingVisit='';editingAppointment='';page='home';render();toast('Το αντίγραφο επαναφέρθηκε.');}
 }catch(err){if(e.target.id==='hospitalToggle')e.target.checked=state.settings.hospital;if(e.target.dataset.module)e.target.checked=enabled(e.target.dataset.module);error(err.message);}});
$('closeHelp').addEventListener('click',()=>$('help').close());
['pointerdown','keydown','input','scroll'].forEach(type=>document.addEventListener(type,()=>lastActivity=Date.now(),{passive:true}));
setInterval(()=>{if(account&&Date.now()-lastActivity>=300000){captureRecovery();try{if(page==='visit')persistVisit();}catch{}account=null;page='login';$('help').close();render();toast('Το περιβάλλον κλειδώθηκε μετά από 5 λεπτά αδράνειας. Η διακοπείσα φόρμα μπορεί να ανακτηθεί μετά την είσοδο.');}},10000);
window.addEventListener('beforeunload',e=>{if(['visit','patients','clinical','examinations'].includes(page)&&account){try{if(!flush()){e.preventDefault();e.returnValue='';}}catch{e.preventDefault();e.returnValue='';}}});
window.addEventListener('storage',e=>{if(e.key===DATA_KEY&&account)toast('Τα δεδομένα άλλαξαν σε άλλο παράθυρο. Ανανεώστε πριν συνεχίσετε.');});
