function clinicalAlert(p){const text=p?.clinical?.allergies?.trim();return text?`<aside class="error clinical-alert"><strong>Αλλεργίες / τεκμηρίωση</strong><p>${esc(text)}</p></aside>`:'';}
const smokingOptions=[['unknown','Δεν έχει καταγραφεί'],['never','Μη καπνιστής'],['current','Καπνιστής'],['former','Πρώην καπνιστής']];
function clinicalValues(){return {smoking:$('clinicalSmoking').value,...Object.fromEntries(Object.keys(CLINICAL_FIELDS).map(k=>[k,$('clinical_'+k).value]))};}
function clinicalPage(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα φανταστικό ασθενή.</p>';const c=p.clinical||emptyClinical();return `<section class="card">${patientSelect('clinicalPatient',p.id)}<h2>${esc(p.name)}</h2><p>Α.Μ.Κ.Α.: ${esc(p.amka)||'—'} · ${p.age} ετών</p>${clinicalAlert(p)}<div class="row">${button('Επισκέψεις / παρακολούθηση','record',p.id,'secondary')}${button('Εξετάσεις & έγγραφα','openExams',p.id,'secondary')}${button('Νέα επίσκεψη','newVisit',p.id)}</div></section><form id="clinicalForm"><section class="card"><div class="eyebrow">Επίπεδο Β · Ιατρικός φάκελος</div><h2>Ιατρικό ιστορικό</h2>${select('Καπνιστής','clinicalSmoking',smokingOptions,c.smoking)}<div class="split">${['familyHistory','medications','allergies','diagnoses'].map(k=>`<label>${CLINICAL_FIELDS[k]}<textarea id="clinical_${k}">${esc(c[k])}</textarea></label>`).join('')}</div><p class="field-hint">Στα φάρμακα καταχωρίζετε την αγωγή για παρακολούθηση. Η επίσημη συνταγογράφηση γίνεται στην ΗΔΙΚΑ.</p></section><section class="card"><div class="eyebrow">Επίπεδο Γ · Ουρολογία–Ανδρολογία</div><h2>Εξειδικευμένο ιστορικό</h2>${['urologyHistory','andrologyHistory','luts'].map(k=>`<label>${CLINICAL_FIELDS[k]}<textarea id="clinical_${k}" ${k==='luts'?'placeholder="Ελεύθερη καταγραφή δυσκολίας ούρησης, συχνουρίας, νυκτουρίας ή άλλων συμπτωμάτων του φανταστικού περιστατικού."':''}>${esc(c[k])}</textarea></label>`).join('')}<p class="field-hint">Προαιρετικά πεδία με ελεύθερο κείμενο. Δεν απαιτείται άκαμπτο έντυπο.</p><div id="formError" role="alert"></div><button type="submit">SAVE · Αποθήκευση ιατρικού ιστορικού</button></section></form>`;}
function examinationsPage(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα φανταστικό ασθενή.</p>';const e=(state.examinations||[]).find(x=>x.id===editingExamination&&x.patientId===p.id);const list=(state.examinations||[]).filter(x=>x.patientId===p.id&&(!examCategory||x.category===examCategory)).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="card">${patientSelect('examPatient',p.id)}<h2>${esc(p.name)}</h2>${clinicalAlert(p)}<div class="row">${button('Ιατρικός φάκελος','openClinical',p.id,'secondary')}${button('Επισκέψεις','record',p.id,'secondary')}${button('Νέα εξέταση','newExam')}</div>${select('Φίλτρο εξετάσεων','examTypeFilter',[['','Όλες οι εξετάσεις'],...Object.entries(EXAM_TYPES)],examCategory)}</section><section class="card"><h2>${e?'Επεξεργασία':'Καταχώριση'} εξέτασης</h2><form id="examForm"><div class="grid">${select('Κατηγορία εξέτασης','examCategory',Object.entries(EXAM_TYPES),e?.category||examCategory||'ultrasound')}${field('Ημερομηνία · ΗΗ/ΜΜ/ΕΕΕΕ','examDate',e?displayDate(e.date):displayDate(today()),'text','required inputmode="numeric" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}"')}${field('Τίτλος εξέτασης','examTitle',e?.title||'','text','required maxlength="200"')}</div><div class="split"><label>Αποτελέσματα / τιμή και μονάδα<textarea id="examResult">${esc(e?.result||'')}</textarea></label><label>Τιμές αναφοράς εργαστηρίου<textarea id="examRange">${esc(e?.referenceRange||'')}</textarea></label></div><label>Γνωμάτευση / παρατηρήσεις εξέτασης<textarea id="examNotes">${esc(e?.notes||'')}</textarea></label><label>Συνημμένα αρχεία εξέτασης<input type="file" id="examFiles" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.dcm,.zip"></label><p class="field-hint">PDF, εικόνες, DICOM ή ZIP σειράς εξέτασης, έως 20 MB ανά αρχείο και 100 MB συνολικά. Η αποθήκευση γίνεται τοπικά στον browser (IndexedDB). Για DICOM/ZIP παρέχεται φύλαξη και λήψη, όχι διαγνωστικός viewer. Μη αποθηκευμένα αρχεία πρέπει να επιλεγούν ξανά μετά από ανανέωση/κλείδωμα.</p>${e?.files.map(f=>`<label><input type="checkbox" data-remove-file="${esc(f.id)}">Αφαίρεση κατά την αποθήκευση: ${esc(f.name)}</label>`).join('')||''}<div id="formError" role="alert"></div><button type="submit">SAVE · Αποθήκευση εξέτασης και αρχείων</button></form></section><section class="card"><h2>Ιστορικό εξετάσεων · ${list.length}</h2>${list.map(x=>`<article class="exam-entry"><div class="row between"><h3>${esc(x.title)}</h3><span class="pill">${displayDate(x.date)} · ${EXAM_TYPES[x.category]}</span></div><p class="prewrap"><strong>Αποτέλεσμα:</strong> ${esc(x.result)||'—'}</p><p class="prewrap"><strong>Τιμές αναφοράς:</strong> ${esc(x.referenceRange)||'—'}</p><p class="prewrap">${esc(x.notes)}</p><ul>${x.files.map(f=>`<li>${esc(f.name)} · ${(f.size/1024).toFixed(1)} KB ${button('Λήψη αρχείου','downloadExam',f.id,'secondary')}${/^image\/(png|jpeg|webp)$/.test(f.type)?button('Προβολή εικόνας','previewExam',f.id,'secondary'):''}</li>`).join('')}</ul><div class="row">${button('Επεξεργασία','editExam',x.id,'secondary')}${button('Διαγραφή δοκιμαστικής εξέτασης','removeExam',x.id,'danger')}</div></article>`).join('')||'<p>Δεν έχουν καταχωριστεί εξετάσεις με αυτό το φίλτρο.</p>'}</section>${optionsActions()}`;}
async function blobFingerprint(blob){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join('');}
async function saveExamination(){if(!doctor())throw Error('Απαιτείται γιατρός.');const old=(state.examinations||[]).find(e=>e.id===editingExamination);const date=isoDate($('examDate').value);if(!date)throw Error('Συμπληρώστε έγκυρη ημερομηνία εξέτασης.');const selected=[...$('examFiles').files];for(const f of selected)checkFile(f);const removed=new Set([...document.querySelectorAll('[data-remove-file]:checked')].map(e=>e.dataset.removeFile));const retained=(old?.files||[]).filter(f=>!removed.has(f.id));const total=(state.examinations||[]).filter(e=>e.id!==old?.id).flatMap(e=>e.files).reduce((n,f)=>n+f.size,0)+retained.reduce((n,f)=>n+f.size,0)+selected.reduce((n,f)=>n+f.size,0);if(total>100*1024*1024)throw Error('Το σύνολο αρχείων υπερβαίνει τα 100 MB του demo.');const added=[];try{for(const f of selected){const id=uid();await putFile(id,f);added.push({id,name:f.name,type:f.type||'application/octet-stream',size:f.size});}const item={id:old?.id||uid(),patientId:selectedPatient,category:$('examCategory').value,date,title:$('examTitle').value.trim(),result:$('examResult').value,referenceRange:$('examRange').value,notes:$('examNotes').value,files:[...retained,...added]};update(s=>{s.examinations||=[];const i=s.examinations.findIndex(e=>e.id===item.id);if(i<0)s.examinations.push(item);else s.examinations[i]=item;});}catch(err){for(const f of added){try{await deleteFile(f.id);}catch{}}throw err;}for(const id of removed)await deleteFile(id);editingExamination='';render();toast('Η εξέταση και τα αρχεία αποθηκεύτηκαν τοπικά.');}
